        "schoolLevelBadge": {
          "type": "string",
          "minLength": 1
        },
        "namingState": {
          "enum": [
            "verified_components",
            "partial_components"
          ]
        },
        "sourceIds": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "uniqueItems": true
        },
        "fieldEvidence": {
          "type": "object",
